{{ config(materialized='incremental',schema='DBT_MARTS',unique_key='customer_month_key',incremental_strategy='merge',tags=['gold','fact','snapshot']) }}
with months as (select calendar_date month_start,month_end,year_month from {{ ref('dim_date') }} where day_of_month=1),spine as (select s.*,m.month_start,m.month_end,m.year_month from {{ ref('int_subscription_clean') }} s join months m on m.month_start between date_trunc('month',s.contract_start_date) and date_trunc('month',coalesce(s.contract_end_date,current_date()))) select {{ generate_surrogate_key(['sp.customer_id','sp.month_start']) }} customer_month_key,{{ generate_surrogate_key(['sp.customer_id']) }} customer_key,{{ generate_surrogate_key(['sp.subscription_id']) }} subscription_key,{{ generate_surrogate_key(['sp.plan_name','sp.plan_tier']) }} plan_key,to_number(to_char(sp.month_start,'YYYYMMDD')) month_date_key,sp.year_month,sp.month_start,sp.month_end,sp.contract_type,sp.base_monthly_price,greatest(datediff(month,sp.contract_start_date,sp.month_end),0) tenure_months_at_month_end,iff(sp.status='ACTIVE' and (sp.contract_end_date is null or sp.contract_end_date>sp.month_end),1,0) active_at_month_end_count,current_timestamp() dw_loaded_at from spine sp qualify row_number() over(partition by sp.customer_id,sp.month_start order by sp.contract_start_date desc,sp.subscription_id desc)=1
